-- Recetario: platos con técnica de cocinero que el planificador usa como inspiración.
-- Global (lo escribe solo service_role) y legible por cualquier usuario autenticado.

create table public.recetario (
  id           uuid primary key default gen_random_uuid(),
  slug         text not null unique check (slug ~ '^[a-z0-9-]{3,60}$'),
  titulo       text not null check (char_length(titulo) between 3 and 160),
  cocina       text not null,
  momento      text not null check (momento in ('almuerzo', 'cena')),
  raciones     smallint not null default 2 check (raciones between 1 and 12),
  minutos      smallint not null check (minutos between 1 and 600),
  aparato      text not null,
  etiquetas    text[] not null default '{}',
  ingredientes text[] not null,
  pasos        text[] not null,
  truco        text not null default '',
  conservacion text not null default '',
  sobras       boolean not null default false,
  congela      boolean not null default false,
  coste        text not null default 'barato' check (coste in ('barato', 'medio', 'oferta')),
  meses        smallint[],
  created_at   timestamptz not null default now()
);
alter table public.recetario enable row level security;
revoke all on public.recetario from anon, authenticated;
grant select on public.recetario to authenticated;
create policy recetario_leer on public.recetario for select to authenticated using (true);

-- Favoritos de cada casa: el planificador los propone más a menudo.
create table public.recetario_favoritos (
  household_id uuid not null default public.my_household() references public.households (id) on delete cascade,
  receta_id    uuid not null references public.recetario (id) on delete cascade,
  created_at   timestamptz not null default now(),
  primary key (household_id, receta_id)
);
alter table public.recetario_favoritos enable row level security;
revoke all on public.recetario_favoritos from anon;
create policy recetario_favoritos_todo on public.recetario_favoritos
  for all to authenticated
  using (household_id = public.my_household())
  with check (household_id = public.my_household());

-- Datos del recetario (generado por scripts/recetario.py; no editar a mano).
insert into public.recetario (slug, titulo, cocina, momento, raciones, minutos, aparato, etiquetas, ingredientes, pasos, truco,
  conservacion, sobras, congela, coste, meses) values
($r$secreto-pimienta$r$,$r$Secreto ibérico con salsa de pimienta y arroz blanco$r$,$r$española$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$De la casa$r$,$r$Plato de cocinero$r$,$r$Cerdo$r$]::text[],array[$r$400 g de secreto ibérico$r$,$r$150 g de arroz largo$r$,$r$1 chalota o media cebolla pequeña$r$,$r$1 cucharada de pimienta negra en grano$r$,$r$200 ml de nata para cocinar$r$,$r$100 ml de caldo de carne o de pollo$r$,$r$30 ml de brandy (opcional, ver truco)$r$,$r$10 g de mantequilla$r$]::text[],array[$r$Saca el secreto de la nevera 20 minutos antes y sécalo bien con papel: carne fría y húmeda no se dora, se cuece.$r$,$r$Pon el arroz en la arrocera (o cuécelo 11 minutos en agua con sal) y déjalo tapado reposando.$r$,$r$Machaca la pimienta en el mortero, que quede gruesa, no en polvo. Calienta la sartén a fuego fuerte, sin aceite: el secreto suelta su propia grasa.$r$,$r$Marca el secreto entero 3 minutos por cara sin moverlo, hasta que tenga costra tostada. Sálalo al darle la vuelta y sácalo a una tabla a reposar 5 minutos tapado con papel de aluminio flojo.$r$,$r$En la misma sartén, a fuego medio, pocha la chalota picada con la mantequilla 2 minutos y añade la pimienta 30 segundos para que suelte aroma.$r$,$r$Desglasa con el brandy (o directamente con el caldo) rascando el fondo: ese tostado pegado es la salsa. Deja hervir 2-3 minutos hasta que no huela a alcohol, añade el caldo y reduce a la mitad.$r$,$r$Echa la nata, cuece 3-4 minutos hasta que napa la cuchara y ajusta de sal. Filetea el secreto en tiras al bies, echa su jugo del reposo a la salsa y sirve con el arroz.$r$]::text[],$r$El reposo y el jugo que suelta van a la salsa: no lo tires. Si queréis cero alcohol por la lactancia, sustituye el brandy por caldo con unas gotas de salsa Perrins.$r$,$r$Mejor recién hecho; la salsa aguanta 2 días en la nevera.$r$,false,false,$r$medio$r$,null),
($r$solomillo-cerveza$r$,$r$Solomillo de cerdo a la cerveza con cebolla confitada y patatas panaderas$r$,$r$española$r$,$r$almuerzo$r$,2,50,$r$Horno$r$,array[$r$De la casa$r$,$r$Plato de cocinero$r$,$r$Cerdo$r$]::text[],array[$r$1 solomillo de cerdo (unos 450 g)$r$,$r$2 patatas medianas$r$,$r$2 cebollas$r$,$r$330 ml de cerveza tostada (o sin alcohol)$r$,$r$1 cucharadita de miel$r$,$r$1 cucharadita de mostaza$r$,$r$1 hoja de laurel$r$,$r$Tomillo seco$r$]::text[],array[$r$Horno a 190 °C. Corta las patatas en rodajas de medio centímetro y una cebolla en juliana; mézclalas con aceite, sal y tomillo en una fuente y hornea 25 minutos.$r$,$r$Mientras, quita al solomillo la telilla plateada con la punta del cuchillo (si no, se encoge y se arquea). Salpimiéntalo.$r$,$r$Dóralo en una sartén muy caliente con un hilo de aceite, 1 minuto por cada lado, hasta que esté tostado por todas partes. Ponlo sobre las patatas.$r$,$r$En la misma sartén, pocha la otra cebolla en juliana a fuego medio 10 minutos con una pizca de sal, hasta que esté dorada y dulce.$r$,$r$Vierte la cerveza, añade el laurel, la miel y la mostaza y deja hervir a borbotones 10-12 minutos, hasta que reduzca a la mitad y espese.$r$,$r$Hornea el solomillo 12-14 minutos (debe quedar ligeramente rosado en el centro). Sácalo y déjalo reposar 5 minutos antes de cortarlo en medallones gruesos.$r$,$r$Sirve los medallones sobre las patatas con la cebolla y la salsa por encima.$r$]::text[],$r$La telilla plateada fuera y el reposo después: así el solomillo queda jugoso y no seco. La cerveza hierve más de 10 minutos y pierde casi todo el alcohol; si queréis cero, usad cerveza sin alcohol, que funciona igual.$r$,$r$Aguanta 2 días en nevera; recalienta suave con la salsa para que no se seque.$r$,true,false,$r$medio$r$,null),
($r$lentejas-riojana$r$,$r$Lentejas a la riojana con chorizo$r$,$r$española$r$,$r$almuerzo$r$,2,60,$r$Vitrocerámica o inducción$r$,array[$r$De la casa$r$,$r$Legumbres$r$,$r$Guisos de cuchara$r$,$r$Para dejar hecho$r$]::text[],array[$r$250 g de lentejas pardinas$r$,$r$1 chorizo para cocinar (unos 150 g)$r$,$r$1 cebolla$r$,$r$1 pimiento verde$r$,$r$1 zanahoria$r$,$r$1 patata$r$,$r$2 dientes de ajo$r$,$r$1 tomate maduro$r$,$r$1 cucharadita de pimentón dulce de la Vera$r$,$r$1 hoja de laurel$r$]::text[],array[$r$Lava las lentejas y ponlas en la olla con agua fría que las cubra tres dedos, el laurel, la zanahoria entera y media cebolla. Arranca el hervor y baja a fuego suave.$r$,$r$Mientras, en una sartén, pocha la otra media cebolla, el pimiento y los ajos muy picados 10 minutos a fuego bajo: el sofrito tiene que estar blando y dulce, no tostado.$r$,$r$Añade el tomate rallado y deja que pierda el agua, 5 minutos. Aparta del fuego, echa el pimentón y remueve 20 segundos: el pimentón se quema enseguida y amarga.$r$,$r$Echa el sofrito a las lentejas junto con el chorizo en rodajas gruesas y la patata chascada (rompe el trozo con el cuchillo en vez de cortarlo limpio: suelta almidón y espesa el caldo).$r$,$r$Cuece a fuego muy suave 30-35 minutos, sin que hierva fuerte (las lentejas se pelan). Si hace falta, añade agua fría poco a poco.$r$,$r$Saca la zanahoria y la media cebolla cocidas, aplástalas con un cacillo de caldo y devuélvelas a la olla: espesa sin harina. Sal al final y reposa 10 minutos antes de servir.$r$]::text[],$r$Patata chascada y verdura cocida aplastada: así el caldo queda trabado y meloso. Al día siguiente están aún mejores.$r$,$r$4 días en nevera; se congelan muy bien (mejor sin la patata).$r$,true,true,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
($r$risotto-boletus$r$,$r$Risotto de boletus$r$,$r$italiana$r$,$r$almuerzo$r$,2,40,$r$Vitrocerámica o inducción$r$,array[$r$De la casa$r$,$r$Plato de cocinero$r$,$r$Pasta y arroz$r$,$r$Vegetariano$r$]::text[],array[$r$160 g de arroz arborio o carnaroli (o bomba si no hay)$r$,$r$20 g de boletus secos$r$,$r$200 g de champiñones o setas frescas$r$,$r$1 chalota$r$,$r$800 ml de caldo de verduras o de pollo$r$,$r$40 g de parmesano rallado$r$,$r$30 g de mantequilla fría$r$,$r$50 ml de vino blanco (opcional)$r$]::text[],array[$r$Hidrata los boletus en 300 ml de agua caliente 20 minutos. Escúrrelos (pícalos) y cuela el agua con un papel de cocina: va al caldo, es puro sabor. Calienta caldo y agua juntos y mantenlos al fuego mínimo.$r$,$r$Saltea las setas frescas laminadas a fuego fuerte con un hilo de aceite hasta que se doren, sal al final, y resérvalas.$r$,$r$En la misma cazuela, a fuego suave, pocha la chalota picada fina con un poco de aceite 4 minutos. Sube el fuego, echa el arroz y tuéstalo 2 minutos removiendo, hasta que el grano esté brillante y suene.$r$,$r$Si usas vino, échalo y deja que se evapore del todo (1-2 minutos, sin olor a alcohol). Añade los boletus picados.$r$,$r$Ve añadiendo el caldo caliente cucharón a cucharón, removiendo a menudo y esperando a que el arroz lo beba antes del siguiente. Unos 17-18 minutos, hasta que esté al dente.$r$,$r$Fuera del fuego, echa las setas salteadas, la mantequilla fría en dados y el parmesano y remueve con energía 1 minuto: eso es la «mantecatura», lo que lo hace cremoso. Deja reposar 1 minuto tapado y sirve en plato llano: debe extenderse como una ola.$r$]::text[],$r$El caldo siempre caliente y la mantequilla fría al final, fuera del fuego. Si el vino os preocupa, sustitúyelo por un chorrito de agua de los boletus con unas gotas de limón.$r$,$r$Mejor recién hecho; lo que sobre se convierte en croquetas o en tortitas de arroz a la sartén.$r$,false,false,$r$barato$r$,null),
($r$filete-ternera-padron$r$,$r$Filete de ternera a la plancha con patatas al horno y pimientos de Padrón$r$,$r$española$r$,$r$almuerzo$r$,2,35,$r$Horno$r$,array[$r$De la casa$r$,$r$Carne de oferta$r$]::text[],array[$r$2 filetes de ternera gruesos (entrecot, lomo bajo o cadera, unos 400 g)$r$,$r$2 patatas$r$,$r$150 g de pimientos de Padrón$r$,$r$Romero$r$,$r$Sal en escamas$r$]::text[],array[$r$Saca la carne de la nevera 30 minutos antes. Horno a 200 °C: patatas en gajos con piel, aceite, sal y romero, 30 minutos (o 20 en la freidora de aire a 200 °C).$r$,$r$Seca muy bien los filetes con papel. Calienta la sartén o plancha hasta que humee ligeramente y unta la carne, no la sartén, con un poco de aceite.$r$,$r$Marca 2 minutos por cara sin tocar (para un filete de 2 cm, al punto menos). Dale la vuelta una sola vez.$r$,$r$Saca la carne a un plato caliente y deja que repose 4 minutos: las fibras se relajan y el jugo se queda dentro.$r$,$r$En la misma sartén, saltea los pimientos de Padrón con un hilo de aceite a fuego fuerte hasta que se ampollen, 3 minutos. Sal gorda al final.$r$,$r$Sirve la carne con sal en escamas por encima, las patatas y los pimientos.$r$]::text[],$r$Sal la carne justo antes de la sartén o justo después, nunca media hora antes. Solo cuando la ternera buena esté de oferta.$r$,$r$Mejor al momento.$r$,false,false,$r$oferta$r$,null),
($r$garbanzos-espinacas$r$,$r$Garbanzos con espinacas a la sevillana$r$,$r$española$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Legumbres$r$,$r$Guisos de cuchara$r$,$r$Vegetariano$r$,$r$Rápido$r$]::text[],array[$r$1 bote de garbanzos cocidos (400 g)$r$,$r$300 g de espinacas (frescas o congeladas)$r$,$r$2 rebanadas de pan del día anterior$r$,$r$3 dientes de ajo$r$,$r$1 cucharadita de comino molido$r$,$r$1 cucharadita de pimentón dulce$r$,$r$1 cucharada de vinagre de Jerez o de vino$r$,$r$300 ml de caldo de verduras$r$]::text[],array[$r$Fríe en una cazuela, con un buen chorro de aceite, el pan y los ajos laminados hasta que estén dorados. Sácalos al mortero o al vaso de la batidora.$r$,$r$Añade el comino, el pimentón, el vinagre y un poco de caldo y machaca o tritura hasta tener una pasta espesa: es la majada que da cuerpo al guiso.$r$,$r$En el mismo aceite, saltea las espinacas hasta que se marchiten y pierdan el agua.$r$,$r$Echa los garbanzos lavados, la majada y el resto del caldo. Cuece 10 minutos a fuego suave, hasta que el caldo espese.$r$,$r$Ajusta de sal y deja reposar 5 minutos antes de servir.$r$]::text[],$r$La majada de pan frito, ajo y comino es lo que convierte cuatro ingredientes en un plato andaluz de verdad. Espinacas y garbanzos dan hierro, que viene bien en la lactancia.$r$,$r$3 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$pollo-ajillo$r$,$r$Pollo al ajillo con patatas a lo pobre$r$,$r$española$r$,$r$almuerzo$r$,2,45,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Clásico$r$]::text[],array[$r$4 contramuslos de pollo con piel y hueso, troceados en dos$r$,$r$1 cabeza de ajos$r$,$r$2 patatas$r$,$r$1 pimiento verde$r$,$r$Media cebolla$r$,$r$1 hoja de laurel$r$,$r$100 ml de vino blanco o de caldo de pollo$r$,$r$Perejil$r$]::text[],array[$r$Salpimienta el pollo. En una cazuela amplia con aceite a fuego medio-alto, dóralo con la piel hacia abajo 8 minutos sin tocarlo, hasta que la piel esté crujiente; dale la vuelta 3 minutos más.$r$,$r$Baja el fuego, añade los ajos sin pelar, golpeados con el cuchillo, y el laurel. Tápalo y cocina 15 minutos a fuego suave, girando las piezas de vez en cuando.$r$,$r$Mientras, haz las patatas a lo pobre: patatas en láminas finas, cebolla y pimiento en tiras, en sartén con aceite a fuego medio y tapadas 15 minutos; destapa al final para que se doren.$r$,$r$Destapa el pollo, sube el fuego, añade el vino (o caldo) y deja que hierva 3-4 minutos rascando el fondo hasta que la salsa se reduzca y ya no huela a alcohol.$r$,$r$Termina con perejil picado y sirve con las patatas.$r$]::text[],$r$El ajo con piel se confita sin quemarse y queda dulce: aplástalo sobre el pollo al comerlo.$r$,$r$3 días en nevera.$r$,true,false,$r$barato$r$,null),
($r$albondigas-almendras$r$,$r$Albóndigas en salsa de almendras$r$,$r$española$r$,$r$almuerzo$r$,2,50,$r$Vitrocerámica o inducción$r$,array[$r$Para dejar hecho$r$,$r$Clásico$r$]::text[],array[$r$400 g de carne picada mixta$r$,$r$1 huevo$r$,$r$1 rebanada de pan remojada en leche$r$,$r$2 dientes de ajo$r$,$r$Perejil$r$,$r$Harina para rebozar$r$,$r$1 cebolla$r$,$r$30 g de almendras crudas$r$,$r$400 ml de caldo de pollo$r$,$r$Hebras de azafrán o colorante$r$]::text[],array[$r$Mezcla la carne con el huevo, el pan escurrido, un ajo y el perejil picados, sal y pimienta. Amasa solo lo justo: si se amasa mucho, quedan duras.$r$,$r$Forma bolas del tamaño de una nuez con las manos húmedas, pásalas por harina y dóralas por tandas en una sartén con aceite. No tienen que hacerse por dentro.$r$,$r$En una cazuela con un poco de ese aceite, dora las almendras y el otro ajo, sácalos. Pocha ahí la cebolla picada 10 minutos.$r$,$r$Tritura las almendras y el ajo con un poco de caldo y el azafrán. Échalo a la cazuela con el resto del caldo y hierve 5 minutos.$r$,$r$Añade las albóndigas y cuece 15-20 minutos a fuego suave, moviendo la cazuela en círculos en lugar de usar la cuchara para que no se rompan. Tritura la salsa si la quieres fina.$r$]::text[],$r$La harina del rebozado espesa la salsa sola. Mejor de un día para otro.$r$,$r$4 días en nevera; se congelan en su salsa.$r$,true,true,$r$barato$r$,null),
($r$arroz-horno$r$,$r$Arroz al horno con costilla, morcilla y garbanzos$r$,$r$española$r$,$r$almuerzo$r$,2,60,$r$Horno$r$,array[$r$Pasta y arroz$r$,$r$Plato de cocinero$r$,$r$Cerdo$r$]::text[],array[$r$160 g de arroz redondo$r$,$r$250 g de costilla de cerdo troceada$r$,$r$1 morcilla de cebolla$r$,$r$Medio bote de garbanzos cocidos$r$,$r$1 patata$r$,$r$1 tomate$r$,$r$1 cabeza de ajos pequeña$r$,$r$400 ml de caldo de pollo$r$,$r$1 cucharadita de pimentón dulce$r$,$r$Azafrán o colorante$r$]::text[],array[$r$Horno a 220 °C. Calienta el caldo. En una cazuela de barro o una fuente que pueda ir al fuego, dora la costilla salpimentada con aceite. Sácala.$r$,$r$Dora la patata en rodajas gruesas y medio tomate en rodajas. Sácalos. Marca la morcilla en rodajas gruesas 1 minuto y sácala.$r$,$r$Ralla el otro medio tomate, sofríelo 3 minutos, aparta del fuego, añade el pimentón y el arroz y remueve para que se impregne.$r$,$r$Pasa todo a la fuente (si tu cazuela no va al horno): el arroz en una capa fina, los garbanzos, la costilla, y encima las patatas, el tomate, la morcilla y la cabeza de ajos en el centro.$r$,$r$Vierte el caldo hirviendo con el azafrán (el doble de volumen que de arroz) y mete al horno 18-20 minutos, sin tocar.$r$,$r$Saca y deja reposar 5 minutos tapado con un paño.$r$]::text[],$r$El caldo tiene que entrar hirviendo y el arroz en capa fina: así queda suelto y con costra arriba.$r$,$r$2 días en nevera; recalienta con un chorrito de caldo.$r$,true,false,$r$barato$r$,null),
($r$merluza-verde$r$,$r$Merluza en salsa verde con patatas$r$,$r$española$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Pescado$r$,$r$Rápido$r$,$r$Clásico$r$]::text[],array[$r$4 rodajas de merluza (frescas o congeladas y descongeladas)$r$,$r$2 patatas$r$,$r$3 dientes de ajo$r$,$r$1 cucharada de harina$r$,$r$250 ml de caldo de pescado o agua$r$,$r$Mucho perejil$r$,$r$Un puñado de guisantes congelados$r$]::text[],array[$r$Cuece las patatas en rodajas de 1 cm en agua con sal 12 minutos, que queden enteras. Escúrrelas guardando un poco del agua.$r$,$r$En una cazuela baja, a fuego suave, dora los ajos picados en aceite sin que cojan color oscuro. Echa la harina y remueve 1 minuto.$r$,$r$Añade el caldo caliente poco a poco sin dejar de remover, y deja que hierva 3 minutos: es la base de la salsa.$r$,$r$Coloca las rodajas de merluza saladas y los guisantes y cocina 3 minutos por cada lado moviendo la cazuela en vaivén: la gelatina del pescado liga la salsa.$r$,$r$Añade las patatas y mucho perejil picado, 1 minuto más, y sirve.$r$]::text[],$r$Menear la cazuela en vez de remover: así la salsa engorda con la gelatina de la merluza sin romperla.$r$,$r$Mejor al momento.$r$,false,false,$r$barato$r$,null),
($r$carrilleras-vino$r$,$r$Carrilleras de cerdo al vino tinto con puré de patata$r$,$r$española$r$,$r$almuerzo$r$,2,150,$r$Vitrocerámica o inducción$r$,array[$r$Plato de cocinero$r$,$r$Para dejar hecho$r$,$r$Cerdo$r$]::text[],array[$r$4 carrilleras de cerdo (unos 600 g)$r$,$r$1 cebolla$r$,$r$1 zanahoria$r$,$r$1 puerro$r$,$r$2 dientes de ajo$r$,$r$250 ml de vino tinto$r$,$r$250 ml de caldo de carne$r$,$r$1 cucharada de tomate concentrado$r$,$r$Laurel y tomillo$r$,$r$Para el puré: 3 patatas, 30 g de mantequilla, leche caliente$r$]::text[],array[$r$Limpia las carrilleras de grasa y telillas, salpimiéntalas y enharínalas ligeramente. Dóralas en una cazuela con aceite a fuego fuerte hasta que estén bien tostadas. Sácalas.$r$,$r$Baja el fuego y pocha en la misma grasa la verdura picada en dados 15 minutos, hasta que esté blanda y algo caramelizada. Añade el tomate concentrado y tuéstalo 2 minutos.$r$,$r$Vierte el vino, sube el fuego y deja que hierva 5 minutos rascando el fondo, hasta que se reduzca a la mitad y no huela a alcohol.$r$,$r$Vuelve a meter las carrilleras, cubre con el caldo, añade laurel y tomillo, tapa y cuece a fuego mínimo 2 horas (o 40 minutos en olla a presión), hasta que se deshagan con una cuchara.$r$,$r$Saca la carne, tritura la salsa y redúcela si está líquida hasta que brille y napa.$r$,$r$Para el puré, cuece las patatas, pásalas por el pasapurés (la batidora las vuelve chicle) y monta con la mantequilla fría y la leche caliente.$r$]::text[],$r$Dos horas de guiso: el alcohol se ha ido por completo y queda solo el sabor del vino. Se hacen mejor en cantidad doble: la mitad, al congelador.$r$,$r$4 días en nevera; se congelan perfectamente en su salsa.$r$,true,true,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
($r$judias-costilla$r$,$r$Alubias blancas estofadas con costilla y verduras$r$,$r$española$r$,$r$almuerzo$r$,2,90,$r$Vitrocerámica o inducción$r$,array[$r$Legumbres$r$,$r$Guisos de cuchara$r$,$r$Para dejar hecho$r$]::text[],array[$r$200 g de alubias blancas secas (en remojo la noche antes)$r$,$r$250 g de costilla de cerdo adobada o fresca$r$,$r$1 cebolla$r$,$r$1 pimiento rojo$r$,$r$1 zanahoria$r$,$r$2 dientes de ajo$r$,$r$1 cucharadita de pimentón$r$,$r$1 hoja de laurel$r$]::text[],array[$r$Pon las alubias escurridas en agua fría con la costilla, media cebolla, el laurel y la zanahoria. Arranca el hervor y espuma bien.$r$,$r$Cuando hierva, «asústalas» dos veces con un vaso de agua fría: así la piel no se rompe y quedan tiernas por igual.$r$,$r$Mientras, pocha la otra media cebolla, el pimiento y el ajo picados 12 minutos a fuego bajo; fuera del fuego, el pimentón. Añádelo a la olla.$r$,$r$Cuece tapado a fuego mínimo 1 hora, hasta que estén tiernas (o 25 minutos en olla a presión).$r$,$r$Sala al final, aplasta unas cuantas alubias contra la pared de la olla para espesar y deja reposar.$r$]::text[],$r$Hervor mínimo, sin remover con cuchara (mueve la olla): alubia entera y caldo cremoso.$r$,$r$4 días en nevera; se congelan.$r$,true,true,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
($r$caballa-horno$r$,$r$Caballa al horno con patatas, pimiento y limón$r$,$r$española$r$,$r$almuerzo$r$,2,40,$r$Horno$r$,array[$r$Pescado$r$,$r$Barato$r$]::text[],array[$r$2 caballas limpias y abiertas en lomos$r$,$r$2 patatas$r$,$r$1 pimiento rojo$r$,$r$1 cebolla$r$,$r$1 limón$r$,$r$Ajo y perejil$r$,$r$Orégano$r$]::text[],array[$r$Horno a 200 °C. Patatas en rodajas finas, cebolla y pimiento en tiras, con aceite, sal y orégano en una fuente. Hornea 25 minutos.$r$,$r$Haz un ajillo: 2 ajos y perejil picados con 3 cucharadas de aceite y el zumo de medio limón.$r$,$r$Seca los lomos de caballa, sálalos y colócalos sobre las patatas con la piel hacia arriba. Unos cortes en la piel evitan que se encoja.$r$,$r$Hornea 8-10 minutos, solo hasta que la carne se separe en lascas.$r$,$r$Al sacar, riega con el ajillo y sirve con el resto del limón.$r$]::text[],$r$La caballa es pescado azul con omega 3 y poco mercurio: ideal en la lactancia y de las más baratas.$r$,$r$Mejor al momento; lo que sobre, desmigado, sirve para unas tostas.$r$,false,false,$r$barato$r$,null),
($r$arroz-meloso-setas$r$,$r$Arroz meloso de pollo y setas$r$,$r$española$r$,$r$almuerzo$r$,2,45,$r$Vitrocerámica o inducción$r$,array[$r$Pasta y arroz$r$,$r$Pollo$r$,$r$De temporada$r$]::text[],array[$r$160 g de arroz redondo o bomba$r$,$r$2 contramuslos de pollo deshuesados$r$,$r$250 g de setas variadas o champiñones$r$,$r$1 cebolla$r$,$r$1 pimiento verde$r$,$r$1 tomate$r$,$r$2 dientes de ajo$r$,$r$1 l de caldo de pollo$r$,$r$Tomillo$r$]::text[],array[$r$Trocea el pollo en dados, salpimienta y dóralo bien en la cazuela con aceite. Sácalo.$r$,$r$Saltea las setas a fuego fuerte hasta que se doren, sin sal hasta el final para que no suelten agua y se cuezan. Sácalas.$r$,$r$Haz el sofrito: cebolla, pimiento y ajo picados 10 minutos a fuego suave, luego el tomate rallado hasta que se oscurezca.$r$,$r$Añade el arroz, remueve 1 minuto, vuelve a meter el pollo y las setas y echa tres cuartas partes del caldo caliente con el tomillo.$r$,$r$Cuece 18 minutos a fuego medio moviendo de vez en cuando y añadiendo caldo si se seca: debe quedar suelto pero con caldo espeso, como una ola.$r$,$r$Deja reposar 2 minutos y sirve.$r$]::text[],$r$Setas doradas aparte y sal solo al final: si no, sueltan agua y saben a hervido.$r$,$r$Mejor recién hecho.$r$,false,false,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
($r$pisto-huevo$r$,$r$Pisto manchego con huevo a la plancha bien hecho$r$,$r$española$r$,$r$almuerzo$r$,2,50,$r$Vitrocerámica o inducción$r$,array[$r$Verduras$r$,$r$Vegetariano$r$,$r$Para dejar hecho$r$]::text[],array[$r$1 calabacín$r$,$r$1 berenjena$r$,$r$1 pimiento rojo$r$,$r$1 pimiento verde$r$,$r$1 cebolla$r$,$r$400 g de tomate triturado$r$,$r$1 cucharadita de azúcar$r$,$r$2 huevos$r$,$r$Pan$r$]::text[],array[$r$Corta todas las verduras en dados del mismo tamaño, de 1 cm.$r$,$r$Pocha la cebolla 10 minutos a fuego suave, añade los pimientos y cocina 10 minutos más.$r$,$r$Añade el calabacín y la berenjena con sal y cocina 10 minutos: cada verdura entra según lo que tarda.$r$,$r$Echa el tomate y el azúcar (le quita la acidez) y deja que se haga a fuego mínimo 20 minutos, hasta que el aceite se separe y brille.$r$,$r$Haz los huevos a la plancha con la yema bien cuajada (tapa la sartén 1 minuto) y sírvelos encima, con pan.$r$]::text[],$r$Cuanto más lento, mejor: el pisto rápido sabe a verdura cocida; el lento, a mermelada salada.$r$,$r$4 días en nevera; se congela (sin el huevo).$r$,true,true,$r$barato$r$,null),
($r$amatriciana$r$,$r$Pasta all'amatriciana$r$,$r$italiana$r$,$r$almuerzo$r$,2,25,$r$Vitrocerámica o inducción$r$,array[$r$Pasta y arroz$r$,$r$Rápido$r$]::text[],array[$r$200 g de bucatini, espaguetis o rigatoni$r$,$r$120 g de panceta o bacon en taco$r$,$r$400 g de tomate triturado$r$,$r$Media guindilla (opcional)$r$,$r$40 g de queso pecorino o parmesano rallado$r$]::text[],array[$r$Corta la panceta en tiras gruesas y ponla en una sartén fría a fuego medio: la grasa se funde poco a poco y la carne queda crujiente por fuera y tierna por dentro.$r$,$r$Cuando esté dorada, añade la guindilla y el tomate. Cuece 12 minutos a fuego suave, hasta que espese.$r$,$r$Cuece la pasta en agua con bastante sal 1 minuto menos de lo que dice el paquete. Guarda un vaso del agua de cocción.$r$,$r$Pasa la pasta a la salsa con un chorro del agua de cocción y saltea 1 minuto a fuego fuerte, moviendo, para que el almidón ligue la salsa.$r$,$r$Fuera del fuego, el queso, y sirve.$r$]::text[],$r$Terminar la pasta en la salsa con su agua es lo que la diferencia de «pasta con tomate por encima».$r$,$r$La salsa se congela; la pasta, mejor al momento.$r$,false,true,$r$barato$r$,null),
($r$ragu-bolones$r$,$r$Ragú a la boloñesa de cocción lenta con tagliatelle$r$,$r$italiana$r$,$r$almuerzo$r$,2,150,$r$Vitrocerámica o inducción$r$,array[$r$Pasta y arroz$r$,$r$Plato de cocinero$r$,$r$Para dejar hecho$r$]::text[],array[$r$250 g de carne picada de ternera$r$,$r$150 g de carne picada de cerdo$r$,$r$1 cebolla$r$,$r$1 zanahoria$r$,$r$1 rama de apio$r$,$r$400 g de tomate triturado$r$,$r$1 cucharada de tomate concentrado$r$,$r$200 ml de leche entera$r$,$r$250 g de tagliatelle (o 160 g por ración del día)$r$,$r$Parmesano$r$]::text[],array[$r$Pica cebolla, zanahoria y apio muy finos (el «soffritto») y póchalos 15 minutos a fuego suave con aceite y una nuez de mantequilla.$r$,$r$Sube el fuego, añade la carne y no la remuevas hasta que se dore por debajo; después desmenúzala y dórala bien. Que se tueste, no que se cueza en su jugo.$r$,$r$Añade la leche y deja que se evapore casi del todo: suaviza la carne y le da la textura tierna de la receta de Bolonia.$r$,$r$Añade el tomate concentrado, tuéstalo 1 minuto, y luego el tomate triturado y un vaso de agua. Sal.$r$,$r$Cuece destapado a fuego mínimo 2 horas, removiendo de vez en cuando y añadiendo agua si se seca. Tiene que quedar espeso y brillante.$r$,$r$Mezcla con la pasta recién escurrida y un poco de su agua, y sirve con parmesano.$r$]::text[],$r$Leche antes que el tomate y dos horas de fuego mínimo: es lo que convierte una boloñesa normal en un ragú. Haced el doble y congelad la mitad.$r$,$r$4 días en nevera; se congela muy bien.$r$,true,true,$r$barato$r$,null),
($r$pasta-ceci$r$,$r$Pasta e ceci (pasta con garbanzos a la romana)$r$,$r$italiana$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Legumbres$r$,$r$Pasta y arroz$r$,$r$Barato$r$,$r$Vegetariano$r$]::text[],array[$r$1 bote de garbanzos cocidos (400 g)$r$,$r$120 g de pasta corta (ditalini, coditos)$r$,$r$2 dientes de ajo$r$,$r$1 rama de romero$r$,$r$1 cucharada de tomate concentrado$r$,$r$600 ml de caldo de verduras$r$,$r$Parmesano$r$]::text[],array[$r$Dora a fuego suave los ajos laminados y el romero en un buen chorro de aceite, 2 minutos: el aceite se perfuma.$r$,$r$Añade el tomate concentrado y tuéstalo 1 minuto. Echa los garbanzos lavados y el caldo, y cuece 10 minutos.$r$,$r$Saca el romero, tritura la mitad de la olla con la batidora y vuelve a mezclar: queda un caldo espeso y cremoso.$r$,$r$Echa la pasta en crudo y cuécela ahí mismo, removiendo, el tiempo del paquete. Añade agua si espesa demasiado.$r$,$r$Sirve con un hilo de aceite crudo, pimienta y parmesano.$r$]::text[],$r$La pasta cocida en la propia crema suelta almidón y lo liga todo: plato de cuchara italiano por menos de 2 €.$r$,$r$2 días en nevera (la pasta absorbe: añade agua al recalentar).$r$,true,false,$r$barato$r$,null),
($r$pollo-cacciatora$r$,$r$Pollo a la cacciatora con polenta o pan$r$,$r$italiana$r$,$r$almuerzo$r$,2,55,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Para dejar hecho$r$]::text[],array[$r$4 contramuslos de pollo con hueso$r$,$r$1 cebolla$r$,$r$1 pimiento rojo$r$,$r$150 g de champiñones$r$,$r$2 dientes de ajo$r$,$r$400 g de tomate troceado$r$,$r$Un puñado de aceitunas negras$r$,$r$Romero y orégano$r$,$r$100 ml de vino tinto o caldo$r$]::text[],array[$r$Salpimienta el pollo y dóralo con la piel hacia abajo hasta que esté muy tostado. Sácalo.$r$,$r$En la grasa, sofríe la cebolla, el pimiento y los champiñones 10 minutos y el ajo al final.$r$,$r$Echa el vino (o caldo) y deja que hierva 3 minutos hasta que reduzca.$r$,$r$Añade el tomate, las hierbas y las aceitunas, y vuelve a meter el pollo con la piel hacia arriba, sin cubrirla.$r$,$r$Cuece semitapado a fuego suave 30 minutos, hasta que la carne se separe del hueso y la salsa espese.$r$,$r$Sirve con polenta cremosa o con pan para mojar.$r$]::text[],$r$Piel fuera de la salsa: así no se reblandece y aporta sabor tostado.$r$,$r$4 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$orecchiette-brocoli$r$,$r$Pasta con brócoli y salchicha$r$,$r$italiana$r$,$r$almuerzo$r$,2,25,$r$Vitrocerámica o inducción$r$,array[$r$Pasta y arroz$r$,$r$Rápido$r$]::text[],array[$r$200 g de orecchiette u otra pasta corta$r$,$r$1 brócoli pequeño$r$,$r$3 salchichas frescas de cerdo$r$,$r$2 dientes de ajo$r$,$r$Guindilla (opcional)$r$,$r$Parmesano$r$,$r$Ralladura de limón$r$]::text[],array[$r$Cuece los ramilletes de brócoli en el agua de la pasta 4 minutos y sácalos con una espumadera. En esa misma agua, cuece la pasta.$r$,$r$Quita la piel a las salchichas y desmigaja la carne en la sartén con un hilo de aceite; dórala bien a fuego medio-alto.$r$,$r$Añade el ajo laminado y la guindilla 1 minuto, luego el brócoli, y aplástalo un poco con la cuchara para que se haga crema.$r$,$r$Pasa la pasta a la sartén con un cucharón del agua y saltea 1 minuto a fuego fuerte.$r$,$r$Termina con parmesano y ralladura de limón.$r$]::text[],$r$El brócoli aplastado hace de salsa: no hace falta nata.$r$,$r$Mejor al momento.$r$,false,false,$r$barato$r$,null),
($r$tinga-pollo$r$,$r$Tinga de pollo con tortillas, frijoles y aguacate$r$,$r$mexicana$r$,$r$almuerzo$r$,2,45,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Para dejar hecho$r$]::text[],array[$r$2 pechugas o 4 contramuslos de pollo$r$,$r$1 cebolla grande$r$,$r$400 g de tomate triturado$r$,$r$1-2 chiles chipotle en adobo (o 1 cucharadita de pimentón ahumado y una pizca de cayena)$r$,$r$1 cucharadita de orégano$r$,$r$1 bote de frijoles negros (o alubias rojas)$r$,$r$1 aguacate$r$,$r$Tortillas de maíz o trigo$r$,$r$Lima o limón$r$]::text[],array[$r$Cuece el pollo 20 minutos en agua con sal, media cebolla y un ajo. Desmígalo con dos tenedores y guarda el caldo.$r$,$r$Pocha la otra cebolla en juliana 8 minutos, sin dorar del todo.$r$,$r$Tritura el tomate con el chipotle y el orégano, échalo a la sartén y cuece 8 minutos hasta que oscurezca.$r$,$r$Añade el pollo desmigado y un cucharón del caldo; cocina 10 minutos hasta que el pollo se empape y quede jugoso, no aguado.$r$,$r$Calienta los frijoles con un poco de su caldo y aplástalos. Sirve con las tortillas calientes, aguacate y lima.$r$]::text[],$r$El pollo cocido en caldo y luego guisado en la salsa queda jugoso; si lo haces a la plancha, se seca.$r$,$r$4 días en nevera; se congela. Las sobras son burritos para la cena.$r$,true,true,$r$barato$r$,null),
($r$chili-carne$r$,$r$Chili con carne con arroz$r$,$r$mexicana$r$,$r$almuerzo$r$,2,70,$r$Vitrocerámica o inducción$r$,array[$r$Legumbres$r$,$r$Para dejar hecho$r$]::text[],array[$r$300 g de carne picada de ternera$r$,$r$1 bote de alubias rojas$r$,$r$1 cebolla$r$,$r$1 pimiento rojo$r$,$r$2 dientes de ajo$r$,$r$400 g de tomate triturado$r$,$r$1 cucharadita de comino$r$,$r$1 cucharadita de pimentón ahumado$r$,$r$Una pizca de cayena$r$,$r$1 onza de chocolate negro$r$,$r$150 g de arroz$r$]::text[],array[$r$Dora la carne en una cazuela muy caliente sin removerla al principio, para que se tueste. Sácala.$r$,$r$Pocha la cebolla, el pimiento y el ajo 10 minutos. Añade las especias y tuéstalas 30 segundos.$r$,$r$Vuelve a meter la carne, añade el tomate y un vaso de agua, y cuece 40 minutos a fuego suave.$r$,$r$Añade las alubias lavadas y el chocolate y cuece 10 minutos más: el chocolate redondea, no se nota.$r$,$r$Sirve con arroz blanco y, si hay, yogur o queso rallado.$r$]::text[],$r$Especias tostadas en la grasa antes del tomate: el sabor se multiplica.$r$,$r$4 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$tacos-pastor$r$,$r$Tacos de cerdo al pastor con piña a la plancha$r$,$r$mexicana$r$,$r$almuerzo$r$,2,35,$r$Vitrocerámica o inducción$r$,array[$r$Cerdo$r$,$r$Rápido$r$]::text[],array[$r$400 g de cinta de lomo o presa de cerdo en filetes finos$r$,$r$2 rodajas de piña natural o en su jugo$r$,$r$1 cebolla morada$r$,$r$Cilantro$r$,$r$Tortillas de maíz$r$,$r$Adobo: 1 cucharada de pimentón, 1 cucharadita de comino, orégano, 1 ajo, zumo de naranja y vinagre$r$]::text[],array[$r$Mezcla los ingredientes del adobo y unta la carne. Déjala al menos 20 minutos (mejor desde la noche anterior).$r$,$r$Pica la cebolla morada fina y cúbrela con zumo de lima y sal: en 10 minutos se vuelve rosa y suave.$r$,$r$Marca la piña en una sartén muy caliente hasta que se caramelice. Pícala.$r$,$r$En la misma sartén, a fuego fuerte, haz la carne por tandas, 2 minutos por cara, para que se tueste. Pícala en tiras.$r$,$r$Calienta las tortillas y monta: carne, piña, cebolla encurtida y cilantro.$r$]::text[],$r$Sartén por tandas: si la llenas, la carne se cuece en su jugo y no se tuesta.$r$,$r$La carne adobada se congela cruda.$r$,false,true,$r$barato$r$,null),
($r$pollo-teriyaki$r$,$r$Pollo teriyaki con arroz y brócoli$r$,$r$asiática$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Rápido$r$]::text[],array[$r$4 contramuslos de pollo deshuesados$r$,$r$150 g de arroz$r$,$r$1 brócoli pequeño$r$,$r$4 cucharadas de salsa de soja$r$,$r$2 cucharadas de miel o azúcar moreno$r$,$r$1 trozo de jengibre$r$,$r$1 ajo$r$,$r$Sésamo$r$]::text[],array[$r$Pon el arroz en la arrocera. Mezcla la soja, la miel, el jengibre rallado, el ajo rallado y 2 cucharadas de agua.$r$,$r$Pon los contramuslos con la piel (o el lado liso) hacia abajo en la sartén fría con una gota de aceite, enciende a fuego medio y déjalos 8 minutos: se dora y se hace la grasa.$r$,$r$Dales la vuelta, 4 minutos más. Retira la grasa sobrante con papel.$r$,$r$Vierte la salsa y deja que burbujee 2-3 minutos girando el pollo hasta que la salsa se vuelva un lacado brillante.$r$,$r$Cuece el brócoli al vapor 4 minutos. Corta el pollo en tiras y sirve con arroz, brócoli, la salsa y sésamo.$r$]::text[],$r$Contramuslo, no pechuga: aguanta el fuego sin secarse y la salsa se pega mejor.$r$,$r$2 días en nevera.$r$,true,false,$r$barato$r$,null),
($r$curry-rojo$r$,$r$Curry rojo tailandés de pollo con leche de coco$r$,$r$asiática$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Rápido$r$]::text[],array[$r$2 pechugas o 4 contramuslos en tiras$r$,$r$1 lata de leche de coco (400 ml)$r$,$r$1-2 cucharadas de pasta de curry rojo$r$,$r$1 pimiento rojo$r$,$r$1 calabacín o un puñado de judías verdes$r$,$r$1 cucharada de salsa de pescado o de soja$r$,$r$1 cucharadita de azúcar$r$,$r$Lima y albahaca o cilantro$r$,$r$150 g de arroz$r$]::text[],array[$r$Pon el arroz. Abre la lata sin agitarla y saca la parte espesa de arriba.$r$,$r$Calienta esa crema de coco en la sartén hasta que hierva y empiece a soltar aceite; añade la pasta de curry y fríela 2 minutos: así se abre el aroma.$r$,$r$Añade el pollo y saltéalo hasta que pierda el color crudo.$r$,$r$Echa el resto de la leche de coco, la verdura, la salsa de pescado y el azúcar. Cuece 8 minutos, sin que hierva a borbotones.$r$,$r$Prueba: debe estar salado, dulce y picante a la vez; corrige con lima. Sirve con hierbas y arroz.$r$]::text[],$r$Freír la pasta de curry en la crema de coco es el gesto que la hace sonar a Tailandia y no a sopa.$r$,$r$3 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$arroz-frito$r$,$r$Arroz frito con cerdo, huevo y verduras$r$,$r$asiática$r$,$r$almuerzo$r$,2,20,$r$Vitrocerámica o inducción$r$,array[$r$Pasta y arroz$r$,$r$Rápido$r$,$r$Aprovechamiento$r$]::text[],array[$r$300 g de arroz cocido del día anterior (frío)$r$,$r$200 g de lomo de cerdo o pollo en dados$r$,$r$2 huevos$r$,$r$1 zanahoria$r$,$r$Un puñado de guisantes$r$,$r$2 cebolletas$r$,$r$3 cucharadas de salsa de soja$r$,$r$1 cucharadita de aceite de sésamo$r$]::text[],array[$r$Ten todo cortado antes de empezar: esto va muy rápido.$r$,$r$Sartén o wok muy caliente con aceite: dora la carne 3 minutos y sácala.$r$,$r$Bate los huevos y haz un revuelto bien cuajado; sácalo.$r$,$r$Saltea la zanahoria en dados y los guisantes 2 minutos, añade el arroz frío y saltea sin parar 3-4 minutos, hasta que el grano se tueste un poco.$r$,$r$Vuelve a meter carne y huevo, la soja alrededor del borde (no encima) y la cebolleta. 1 minuto más y el aceite de sésamo al final.$r$]::text[],$r$Arroz de la víspera, frío y seco: el recién hecho se apelmaza.$r$,$r$2 días en nevera.$r$,false,false,$r$barato$r$,null),
($r$cerdo-jengibre$r$,$r$Cerdo salteado con jengibre y cebolleta$r$,$r$asiática$r$,$r$almuerzo$r$,2,25,$r$Vitrocerámica o inducción$r$,array[$r$Cerdo$r$,$r$Rápido$r$]::text[],array[$r$400 g de lomo o secreto de cerdo en tiras finas$r$,$r$1 trozo de jengibre de 4 cm$r$,$r$1 manojo de cebolletas$r$,$r$1 pimiento verde$r$,$r$3 cucharadas de salsa de soja$r$,$r$1 cucharada de vinagre de arroz o de manzana$r$,$r$1 cucharadita de azúcar$r$,$r$1 cucharadita de maicena$r$,$r$150 g de arroz$r$]::text[],array[$r$Mezcla la carne con 1 cucharada de soja y la maicena: esa capa la protege y queda tierna.$r$,$r$Mezcla aparte el resto de la soja, el vinagre, el azúcar, el jengibre rallado y 3 cucharadas de agua.$r$,$r$Sartén a fuego máximo con aceite: saltea la carne en una capa, 2 minutos sin tocar, otros 2 removiendo. Sácala.$r$,$r$Saltea el pimiento y la parte blanca de la cebolleta 2 minutos.$r$,$r$Vuelve la carne, echa la salsa y remueve 1 minuto hasta que brille. Termina con lo verde de la cebolleta y sirve con arroz.$r$]::text[],$r$La maicena en la carne («velveting») es el truco de restaurante chino para que no quede seca.$r$,$r$2 días en nevera.$r$,false,false,$r$barato$r$,null),
($r$dal-lentejas$r$,$r$Dal de lentejas rojas con arroz basmati$r$,$r$india$r$,$r$almuerzo$r$,2,35,$r$Vitrocerámica o inducción$r$,array[$r$Legumbres$r$,$r$Vegetariano$r$,$r$Barato$r$]::text[],array[$r$200 g de lentejas rojas$r$,$r$1 cebolla$r$,$r$2 dientes de ajo$r$,$r$1 trozo de jengibre$r$,$r$1 tomate$r$,$r$1 cucharadita de cúrcuma$r$,$r$1 cucharadita de comino en grano o molido$r$,$r$1 cucharadita de garam masala o curry en polvo$r$,$r$200 ml de leche de coco (opcional)$r$,$r$150 g de arroz basmati$r$,$r$Limón y cilantro$r$]::text[],array[$r$Lava las lentejas hasta que el agua salga clara. Cuécelas con 700 ml de agua y la cúrcuma 15 minutos, hasta que se deshagan.$r$,$r$Mientras, pocha la cebolla picada 8 minutos hasta que esté dorada, añade el ajo y el jengibre rallados y el tomate picado, 5 minutos más.$r$,$r$Echa el sofrito a las lentejas con la leche de coco y sal. Cuece 5 minutos más.$r$,$r$El «tadka»: en una sartén pequeña, calienta 2 cucharadas de aceite o mantequilla, echa el comino y el garam masala 20 segundos y vierte ese aceite chisporroteante sobre el dal.$r$,$r$Termina con limón y cilantro y sirve con el basmati.$r$]::text[],$r$El tadka al final, especias fritas en grasa caliente, es lo que hace que sepa a la India y no a puré de lentejas.$r$,$r$4 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$tikka-masala$r$,$r$Pollo tikka masala con arroz basmati$r$,$r$india$r$,$r$almuerzo$r$,2,45,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Plato de cocinero$r$]::text[],array[$r$2 pechugas de pollo en dados$r$,$r$1 yogur natural$r$,$r$2 cucharaditas de garam masala o curry$r$,$r$1 cucharadita de pimentón$r$,$r$1 cebolla$r$,$r$2 dientes de ajo$r$,$r$1 trozo de jengibre$r$,$r$400 g de tomate triturado$r$,$r$100 ml de nata$r$,$r$150 g de arroz basmati$r$]::text[],array[$r$Marina el pollo con el yogur, la mitad de las especias, sal y un ajo rallado al menos 30 minutos (o desde la mañana).$r$,$r$Dóralo en la freidora de aire 12 minutos a 200 °C o en sartén muy caliente, que se tueste en los bordes. Reserva.$r$,$r$Pocha la cebolla 10 minutos hasta que esté dorada; añade ajo, jengibre y el resto de las especias 1 minuto.$r$,$r$Echa el tomate y cuece 15 minutos, tritura si la quieres fina y añade la nata.$r$,$r$Mete el pollo en la salsa 5 minutos y sirve con el arroz.$r$]::text[],$r$El yogur ablanda el pollo y el tostado en la freidora imita al horno tandoor.$r$,$r$3 días en nevera; se congela.$r$,true,true,$r$barato$r$,null),
($r$shawarma-pollo$r$,$r$Shawarma de pollo con arroz, ensalada y salsa de yogur$r$,$r$oriente medio$r$,$r$almuerzo$r$,2,40,$r$Horno$r$,array[$r$Pollo$r$]::text[],array[$r$4 contramuslos de pollo deshuesados$r$,$r$1 cucharadita de comino$r$,$r$1 cucharadita de pimentón$r$,$r$Media cucharadita de canela$r$,$r$Media de cúrcuma$r$,$r$1 limón$r$,$r$2 dientes de ajo$r$,$r$1 yogur griego$r$,$r$1 pepino$r$,$r$2 tomates$r$,$r$Media cebolla morada$r$,$r$150 g de arroz$r$]::text[],array[$r$Marina el pollo con las especias, el zumo de medio limón, un ajo rallado, aceite y sal (mínimo 30 minutos).$r$,$r$Hornea a 220 °C 25 minutos, o 15 en la freidora de aire, hasta que tenga los bordes casi quemados.$r$,$r$Salsa: yogur con el otro ajo rallado, un poco de pepino rallado, sal y aceite.$r$,$r$Ensalada: tomate, pepino y cebolla morada en dados pequeños con limón y aceite.$r$,$r$Deja reposar el pollo 5 minutos y córtalo en tiras finas. Sirve con el arroz, la ensalada y la salsa.$r$]::text[],$r$La canela es la nota que da sabor a puesto de shawarma; una pizca, no más.$r$,$r$3 días en nevera. Las sobras, en pan de pita, son cena.$r$,true,false,$r$barato$r$,null),
($r$kofta-cuscus$r$,$r$Kofta de carne con cuscús y yogur con menta$r$,$r$oriente medio$r$,$r$almuerzo$r$,2,35,$r$Freidora de aire$r$,array[$r$Rápido$r$]::text[],array[$r$400 g de carne picada (cordero o mixta)$r$,$r$Media cebolla rallada$r$,$r$Perejil y menta frescos$r$,$r$1 cucharadita de comino$r$,$r$1 cucharadita de pimentón$r$,$r$150 g de cuscús$r$,$r$1 yogur griego$r$,$r$1 limón$r$,$r$1 tomate y 1 pepino$r$]::text[],array[$r$Mezcla la carne con la cebolla rallada y escurrida, las hierbas picadas, las especias y sal. Amasa bien, aquí sí: así quedan compactas.$r$,$r$Forma salchichas alargadas alrededor de brochetas o a mano, y déjalas 10 minutos en la nevera para que se asienten.$r$,$r$Hazlas en la freidora de aire a 200 °C 10-12 minutos, o en sartén a fuego medio-alto, girándolas.$r$,$r$Cuscús: viértele el mismo volumen de agua hirviendo con sal y aceite, tapa 5 minutos y suéltalo con un tenedor.$r$,$r$Sirve con yogur con menta picada y limón y una ensalada de tomate y pepino.$r$]::text[],$r$La cebolla rallada (no picada) mantiene la kofta jugosa sin deshacerla.$r$,$r$Crudas se congelan; hechas, 2 días en nevera.$r$,false,true,$r$barato$r$,null),
($r$shakshuka$r$,$r$Shakshuka con pan y queso fresco$r$,$r$oriente medio$r$,$r$almuerzo$r$,2,30,$r$Vitrocerámica o inducción$r$,array[$r$Vegetariano$r$,$r$Rápido$r$]::text[],array[$r$4 huevos$r$,$r$1 cebolla$r$,$r$2 pimientos rojos$r$,$r$2 dientes de ajo$r$,$r$400 g de tomate triturado$r$,$r$1 cucharadita de comino$r$,$r$1 cucharadita de pimentón$r$,$r$Queso feta o fresco$r$,$r$Pan$r$]::text[],array[$r$Pocha la cebolla y los pimientos en tiras 12 minutos, hasta que estén blandos.$r$,$r$Añade el ajo y las especias 30 segundos, luego el tomate. Cuece 10 minutos hasta que espese.$r$,$r$Haz 4 huecos y casca un huevo en cada uno. Tapa y cocina a fuego suave 8-10 minutos, hasta que la clara y también la yema estén cuajadas (por la lactancia, mejor bien hechas).$r$,$r$Desmigaja el queso por encima y sirve en la sartén, con pan para mojar.$r$]::text[],$r$Tapa y fuego suave: el huevo se hace al vapor sin que la salsa se queme.$r$,$r$La salsa se puede dejar hecha y congelar.$r$,false,true,$r$barato$r$,null),
($r$pollo-mostaza$r$,$r$Pollo a la mostaza con arroz o patatas$r$,$r$francesa$r$,$r$almuerzo$r$,2,35,$r$Vitrocerámica o inducción$r$,array[$r$Pollo$r$,$r$Plato de cocinero$r$]::text[],array[$r$4 contramuslos de pollo$r$,$r$1 chalota$r$,$r$2 cucharadas de mostaza de Dijon$r$,$r$1 cucharada de mostaza antigua$r$,$r$150 ml de nata$r$,$r$150 ml de caldo de pollo$r$,$r$Tomillo o estragón$r$,$r$150 g de arroz o 2 patatas$r$]::text[],array[$r$Salpimienta el pollo y dóralo bien por ambos lados. Sácalo.$r$,$r$Baja el fuego y pocha la chalota picada 2 minutos en la grasa.$r$,$r$Desglasa con el caldo rascando el fondo, añade las dos mostazas y el tomillo.$r$,$r$Vuelve a meter el pollo y cuece tapado 15 minutos a fuego suave.$r$,$r$Saca el pollo, añade la nata a la salsa y redúcela 3 minutos hasta que napa la cuchara. Sirve con arroz o patatas.$r$]::text[],$r$Dos mostazas: la de Dijon da el picor, la antigua da textura y aspecto de bistró.$r$,$r$3 días en nevera.$r$,true,false,$r$barato$r$,null),
($r$ternera-borgona$r$,$r$Ternera guisada a la borgoñona$r$,$r$francesa$r$,$r$almuerzo$r$,2,150,$r$Vitrocerámica o inducción$r$,array[$r$Plato de cocinero$r$,$r$Para dejar hecho$r$]::text[],array[$r$500 g de morcillo o aguja de ternera en dados grandes$r$,$r$100 g de bacon en taco$r$,$r$200 g de champiñones$r$,$r$10 cebollitas o 1 cebolla$r$,$r$2 zanahorias$r$,$r$2 dientes de ajo$r$,$r$1 cucharada de harina$r$,$r$300 ml de vino tinto$r$,$r$300 ml de caldo de carne$r$,$r$Laurel y tomillo$r$]::text[],array[$r$Seca bien la carne y dórala por tandas en una cazuela con aceite a fuego fuerte. Sácala.$r$,$r$Dora el bacon en tiras, luego la cebolla y la zanahoria en trozos grandes, y el ajo.$r$,$r$Vuelve la carne, espolvorea la harina y remueve 1 minuto. Vierte el vino y deja que hierva 5 minutos.$r$,$r$Cubre con el caldo, añade las hierbas, tapa y cuece a fuego mínimo 2 horas (o 45 minutos en olla a presión).$r$,$r$En los últimos 15 minutos, añade los champiñones dorados aparte en mantequilla. Sirve con puré o pan.$r$]::text[],$r$Cortes baratos con colágeno (morcillo, aguja) en un guiso largo quedan mejor que los caros. El alcohol del vino se va con la cocción.$r$,$r$4 días en nevera; se congela muy bien.$r$,true,true,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
($r$hachis-parmentier$r$,$r$Hachis parmentier (pastel de carne con puré gratinado)$r$,$r$francesa$r$,$r$almuerzo$r$,2,60,$r$Horno$r$,array[$r$Para dejar hecho$r$,$r$Aprovechamiento$r$]::text[],array[$r$350 g de carne picada (o sobras de guiso desmigadas)$r$,$r$1 cebolla$r$,$r$1 zanahoria$r$,$r$1 cucharada de tomate concentrado$r$,$r$500 g de patatas$r$,$r$30 g de mantequilla$r$,$r$Leche$r$,$r$Nuez moscada$r$,$r$Queso rallado$r$]::text[],array[$r$Cuece las patatas peladas en agua con sal 20 minutos y haz un puré con la mantequilla, leche caliente, sal y nuez moscada.$r$,$r$Pocha la cebolla y la zanahoria picadas 10 minutos. Añade la carne y dórala bien.$r$,$r$Añade el tomate concentrado y un vaso de agua o caldo, y deja que se reduzca 10 minutos hasta que quede jugoso.$r$,$r$En una fuente, la carne abajo y el puré encima; marca surcos con un tenedor y espolvorea queso.$r$,$r$Gratina a 220 °C 15-20 minutos, hasta que los surcos estén dorados.$r$]::text[],$r$Los surcos del tenedor no son decoración: crean puntas que se doran y crujen.$r$,$r$3 días en nevera; se congela entero.$r$,true,true,$r$barato$r$,null),
($r$quiche-lorraine$r$,$r$Quiche lorraine con ensalada verde$r$,$r$francesa$r$,$r$almuerzo$r$,2,55,$r$Horno$r$,array[$r$Para dejar hecho$r$]::text[],array[$r$1 lámina de masa quebrada$r$,$r$150 g de bacon en taco$r$,$r$3 huevos$r$,$r$200 ml de nata$r$,$r$100 ml de leche$r$,$r$80 g de queso emmental rallado$r$,$r$Nuez moscada$r$,$r$Lechuga$r$]::text[],array[$r$Horno a 190 °C. Forra un molde con la masa, pínchala con un tenedor y hornéala 10 minutos con peso encima (garbanzos sobre papel): así la base no queda cruda.$r$,$r$Dora el bacon en tiras en una sartén sin aceite.$r$,$r$Bate los huevos con la nata, la leche, pimienta y nuez moscada (sal poca, el bacon ya sala).$r$,$r$Reparte bacon y queso sobre la base y vierte la mezcla.$r$,$r$Hornea 30-35 minutos, hasta que el centro esté firme al moverlo (bien cuajado). Deja templar 10 minutos y sirve con ensalada.$r$]::text[],$r$Cocer la base antes del relleno es la diferencia entre quiche y masa mojada.$r$,$r$3 días en nevera; se congela en porciones.$r$,true,true,$r$barato$r$,null),
($r$salmon-mostaza-miel$r$,$r$Salmón al horno con mostaza y miel, y verduras asadas$r$,$r$francesa$r$,$r$almuerzo$r$,2,30,$r$Horno$r$,array[$r$Pescado$r$,$r$Rápido$r$]::text[],array[$r$2 lomos de salmón$r$,$r$1 cucharada de mostaza$r$,$r$1 cucharada de miel$r$,$r$1 calabacín$r$,$r$1 pimiento rojo$r$,$r$1 cebolla morada$r$,$r$Limón$r$]::text[],array[$r$Horno a 200 °C. Verduras en trozos con aceite y sal, 15 minutos.$r$,$r$Mezcla mostaza y miel con unas gotas de limón.$r$,$r$Coloca el salmón sobre las verduras, píntalo con la mezcla y hornea 10-12 minutos: el centro debe quedar jugoso.$r$,$r$Sirve con limón.$r$]::text[],$r$El salmón se pasa enseguida: sácalo cuando la lasca se separe pero aún brille en el centro.$r$,$r$2 días en nevera; frío está buenísimo en ensalada.$r$,false,false,$r$barato$r$,null),
($r$hummus-casero$r$,$r$Hummus casero con palitos de zanahoria y pepino$r$,$r$oriente medio$r$,$r$cena$r$,2,10,$r$Sin cocinar$r$,array[$r$Ligero$r$,$r$Picoteo$r$,$r$Vegetariano$r$]::text[],array[$r$1 bote de garbanzos cocidos$r$,$r$1 cucharada de tahini (o de crema de cacahuete en su defecto)$r$,$r$1 limón$r$,$r$1 diente de ajo pequeño$r$,$r$Comino y pimentón$r$,$r$2 zanahorias$r$,$r$1 pepino$r$,$r$Pan de pita o regañás$r$]::text[],array[$r$Lava los garbanzos y guarda 3 cucharadas del líquido del bote.$r$,$r$Tritura los garbanzos con el tahini, el zumo de medio limón, el ajo, comino, sal y el líquido del bote, añadiendo un cubito de hielo: queda más fino y claro.$r$,$r$Tritura 2 minutos largos, hasta que esté sedoso.$r$,$r$Sírvelo con un hilo de aceite, pimentón y los palitos de zanahoria y pepino, con pan de pita.$r$]::text[],$r$El hielo al triturar hace el hummus esponjoso, como el de los buenos libaneses.$r$,$r$4 días en nevera.$r$,true,false,$r$barato$r$,null),
($r$tosta-pimiento-cabra$r$,$r$Tostas de pimiento asado, queso de cabra y miel$r$,$r$española$r$,$r$cena$r$,2,15,$r$Horno$r$,array[$r$Ligero$r$,$r$Rápido$r$]::text[],array[$r$Pan de hogaza o barra$r$,$r$1 bote de pimientos asados (o 2 pimientos rojos asados)$r$,$r$Rulo de queso de cabra$r$,$r$Miel$r$,$r$Tomillo$r$]::text[],array[$r$Tuesta el pan.$r$,$r$Pon encima tiras de pimiento asado y una rodaja de queso de cabra.$r$,$r$Gratina 3-4 minutos en el horno o freidora de aire a 200 °C, hasta que el queso se dore.$r$,$r$Termina con un hilo de miel y tomillo.$r$]::text[],$r$La miel contra el queso de cabra salado es el equilibrio: no te pases, un hilo.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$burritos-frijoles$r$,$r$Burritos de pollo, arroz y frijoles negros$r$,$r$mexicana$r$,$r$cena$r$,2,15,$r$Vitrocerámica o inducción$r$,array[$r$Ligero$r$,$r$Aprovechamiento$r$]::text[],array[$r$Tortillas de trigo grandes$r$,$r$Pollo desmigado o sobras de tinga$r$,$r$Arroz cocido$r$,$r$Medio bote de frijoles negros$r$,$r$Queso rallado$r$,$r$Lechuga y tomate$r$,$r$Lima$r$]::text[],array[$r$Calienta los frijoles con una pizca de comino y aplástalos un poco.$r$,$r$Calienta las tortillas 20 segundos por lado en sartén seca.$r$,$r$Pon en el centro arroz, frijoles, pollo, queso, lechuga y tomate, y unas gotas de lima.$r$,$r$Dobla los lados hacia dentro y enrolla apretando. Dóralos 1 minuto por cara en la sartén para sellar.$r$]::text[],$r$Sellarlos en la sartén con el cierre hacia abajo evita que se abran.$r$,$r$Al momento; rellenos sin verdura se congelan envueltos en film.$r$,false,false,$r$barato$r$,null),
($r$quesadillas-champi$r$,$r$Quesadillas de champiñón y queso$r$,$r$mexicana$r$,$r$cena$r$,2,15,$r$Vitrocerámica o inducción$r$,array[$r$Ligero$r$,$r$Vegetariano$r$,$r$Rápido$r$]::text[],array[$r$4 tortillas de trigo$r$,$r$200 g de champiñones$r$,$r$Media cebolla$r$,$r$Queso rallado para fundir$r$,$r$Pimentón ahumado$r$,$r$Tomate y cebolla para un pico de gallo rápido$r$]::text[],array[$r$Saltea los champiñones laminados con la cebolla a fuego fuerte hasta que estén dorados y secos. Sal y pimentón.$r$,$r$Sobre media tortilla, queso, champiñones y más queso. Dobla.$r$,$r$Dora en sartén seca a fuego medio 2 minutos por cara, aplastando con la espátula.$r$,$r$Corta en triángulos y sirve con un pico de gallo de tomate y cebolla picados con lima.$r$]::text[],$r$Queso abajo y arriba del relleno: hace de pegamento.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$sandwich-club$r$,$r$Sándwich club de pollo$r$,$r$americana$r$,$r$cena$r$,2,15,$r$Vitrocerámica o inducción$r$,array[$r$Ligero$r$]::text[],array[$r$6 rebanadas de pan de molde$r$,$r$1 pechuga de pollo a la plancha (o sobras)$r$,$r$4 lonchas de bacon$r$,$r$Lechuga$r$,$r$1 tomate$r$,$r$Mayonesa$r$]::text[],array[$r$Haz el bacon crujiente en la sartén y la pechuga a la plancha si no tienes sobras; fíletéala fina.$r$,$r$Tuesta el pan.$r$,$r$Monta en dos pisos: pan, mayonesa, lechuga, tomate, pollo; pan, bacon, lechuga; pan.$r$,$r$Pincha con palillos y corta en diagonal.$r$]::text[],$r$Mayonesa de bote: la casera lleva huevo crudo, mejor evitarla mientras Rut da el pecho.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$tostas-champi-jamon$r$,$r$Tostas de champiñones al ajillo con jamón$r$,$r$española$r$,$r$cena$r$,2,15,$r$Vitrocerámica o inducción$r$,array[$r$Ligero$r$,$r$Rápido$r$]::text[],array[$r$Pan de hogaza$r$,$r$250 g de champiñones$r$,$r$2 dientes de ajo$r$,$r$Perejil$r$,$r$Unas lonchas de jamón serrano$r$]::text[],array[$r$Lamina los champiñones y saltéalos a fuego fuerte hasta que se doren.$r$,$r$Añade el ajo laminado y el perejil 1 minuto, sal y pimienta.$r$,$r$Tuesta el pan, frótalo con ajo, pon encima los champiñones y una loncha de jamón.$r$]::text[],$r$Sartén muy caliente y en una sola capa: champiñón dorado, no hervido.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$tabla-picoteo$r$,$r$Tabla de picoteo con pan con tomate$r$,$r$española$r$,$r$cena$r$,2,10,$r$Sin cocinar$r$,array[$r$Ligero$r$,$r$Picoteo$r$]::text[],array[$r$Queso curado o semicurado$r$,$r$Jamón serrano o lomo embuchado$r$,$r$Aceitunas$r$,$r$Pan de barra$r$,$r$2 tomates maduros$r$,$r$Picos o regañás$r$]::text[],array[$r$Ralla los tomates y aliña la pulpa con sal y aceite.$r$,$r$Tuesta el pan y úntalo con el tomate.$r$,$r$Saca el queso y el embutido 15 minutos antes, a temperatura ambiente saben el doble.$r$,$r$Monta la tabla con aceitunas y picos.$r$]::text[],$r$Queso y embutido a temperatura ambiente: la grasa se suaviza y se nota todo el sabor.$r$,$r$Lo que sobre, envuelto, vuelve a la nevera.$r$,false,false,$r$barato$r$,null),
($r$tortilla-patatas$r$,$r$Tortilla de patatas bien cuajada$r$,$r$española$r$,$r$cena$r$,2,40,$r$Vitrocerámica o inducción$r$,array[$r$Ligero$r$,$r$Vegetariano$r$,$r$Clásico$r$]::text[],array[$r$4 huevos$r$,$r$3 patatas medianas$r$,$r$Media cebolla (opcional)$r$,$r$Aceite de oliva abundante$r$]::text[],array[$r$Corta las patatas en láminas finas e irregulares y la cebolla en juliana. Confítalas en abundante aceite a fuego medio-bajo 20 minutos: tienen que quedar tiernas, no fritas.$r$,$r$Escúrrelas muy bien y mézclalas con los huevos batidos y sal. Deja reposar 5 minutos: la patata absorbe el huevo.$r$,$r$Sartén con una cucharada de aceite a fuego medio: echa la mezcla, 4 minutos moviendo la sartén.$r$,$r$Dale la vuelta con un plato y cocina 3-4 minutos más, hasta que esté cuajada por dentro (por la lactancia, mejor sin centro líquido).$r$]::text[],$r$El reposo de la patata en el huevo es lo que la hace jugosa aunque esté bien cuajada.$r$,$r$2 días en nevera; fría, en bocadillo, es otra cena.$r$,true,false,$r$barato$r$,null),
($r$ensalada-garbanzos$r$,$r$Ensalada de garbanzos con atún claro, pimiento y huevo duro$r$,$r$española$r$,$r$cena$r$,2,15,$r$Sin cocinar$r$,array[$r$Ligero$r$,$r$Legumbres$r$]::text[],array[$r$1 bote de garbanzos$r$,$r$2 latas de atún claro$r$,$r$2 huevos$r$,$r$1 pimiento rojo asado o crudo$r$,$r$Media cebolla morada$r$,$r$Aceitunas$r$,$r$Vinagre de Jerez$r$]::text[],array[$r$Cuece los huevos 10 minutos y enfríalos en agua.$r$,$r$Lava los garbanzos. Pica la cebolla fina y deja que repose en el vinagre 5 minutos: pierde el picor.$r$,$r$Mezcla garbanzos, pimiento en tiras, atún escurrido y aceitunas.$r$,$r$Aliña con la cebolla y su vinagre, aceite y sal. Pon encima los huevos en cuartos.$r$]::text[],$r$Atún claro de lata, sí; atún rojo, no, durante la lactancia.$r$,$r$2 días en nevera (sin aliñar).$r$,false,false,$r$barato$r$,null),
($r$wrap-cesar$r$,$r$Wraps de pollo César con salsa de yogur$r$,$r$americana$r$,$r$cena$r$,2,20,$r$Freidora de aire$r$,array[$r$Ligero$r$,$r$Pollo$r$]::text[],array[$r$1 pechuga de pollo$r$,$r$Tortillas de trigo$r$,$r$Lechuga romana$r$,$r$Parmesano$r$,$r$Picatostes o pan tostado$r$,$r$1 yogur griego$r$,$r$1 cucharadita de mostaza$r$,$r$2 anchoas (opcional)$r$,$r$Limón$r$]::text[],array[$r$Haz la pechuga en la freidora de aire a 200 °C 12 minutos con aceite, sal y pimienta. Reposa y corta en tiras.$r$,$r$Salsa: yogur, mostaza, las anchoas machacadas, parmesano rallado, limón y pimienta.$r$,$r$Mezcla la lechuga picada con la salsa.$r$,$r$Rellena las tortillas con lechuga, pollo, picatostes y más parmesano, y enrolla.$r$]::text[],$r$Salsa César con yogur en vez de huevo crudo: igual de sabrosa y segura en la lactancia.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$croque-monsieur$r$,$r$Croque monsieur$r$,$r$francesa$r$,$r$cena$r$,2,20,$r$Horno$r$,array[$r$Ligero$r$]::text[],array[$r$4 rebanadas de pan de molde grueso$r$,$r$4 lonchas de jamón cocido$r$,$r$Queso emmental rallado$r$,$r$Para la bechamel rápida: 15 g de mantequilla, 15 g de harina, 200 ml de leche, nuez moscada$r$]::text[],array[$r$Bechamel: funde la mantequilla, añade la harina 1 minuto y la leche poco a poco, sin dejar de remover, hasta que espese. Sal y nuez moscada.$r$,$r$Unta las rebanadas con un poco de bechamel, pon jamón y queso y cierra.$r$,$r$Cubre la tapa con más bechamel y queso.$r$,$r$Gratina a 220 °C 8-10 minutos (o freidora de aire 6 minutos) hasta que esté dorado y burbujeante.$r$]::text[],$r$La bechamel encima es lo que lo separa de un mixto: crujiente por fuera, cremoso dentro.$r$,$r$Al momento.$r$,false,false,$r$barato$r$,null),
($r$falafel-pita$r$,$r$Pitas de falafel al aire con salsa de yogur$r$,$r$oriente medio$r$,$r$cena$r$,2,30,$r$Freidora de aire$r$,array[$r$Ligero$r$,$r$Vegetariano$r$]::text[],array[$r$1 bote de garbanzos cocidos bien escurridos y secos$r$,$r$Media cebolla$r$,$r$1 diente de ajo$r$,$r$Perejil y cilantro$r$,$r$1 cucharadita de comino$r$,$r$2 cucharadas de harina$r$,$r$Pan de pita$r$,$r$Tomate, pepino, lechuga$r$,$r$Yogur griego con ajo y limón$r$]::text[],array[$r$Tritura los garbanzos, la cebolla, el ajo, las hierbas, el comino y sal a pulsos: debe quedar granulado, no puré.$r$,$r$Añade la harina y forma bolitas aplastadas. Déjalas 15 minutos en la nevera.$r$,$r$Píntalas con aceite y hazlas en la freidora de aire a 200 °C 12 minutos, girando a mitad.$r$,$r$Rellena las pitas calientes con falafel, verdura y salsa de yogur.$r$]::text[],$r$Garbanzos muy secos y triturado grueso: así no se deshacen.$r$,$r$Crudos se congelan.$r$,false,true,$r$barato$r$,null),
($r$crema-calabaza$r$,$r$Crema de calabaza asada con picatostes$r$,$r$francesa$r$,$r$cena$r$,2,40,$r$Horno$r$,array[$r$Ligero$r$,$r$Vegetariano$r$,$r$De temporada$r$]::text[],array[$r$600 g de calabaza$r$,$r$1 zanahoria$r$,$r$1 cebolla$r$,$r$1 patata pequeña$r$,$r$500 ml de caldo de verduras$r$,$r$Una pizca de nuez moscada o jengibre$r$,$r$Pan para picatostes$r$]::text[],array[$r$Horno a 200 °C: calabaza, zanahoria y cebolla en trozos con aceite y sal, 30 minutos, hasta que se tuesten los bordes.$r$,$r$Pásalo a una olla con la patata en trozos y el caldo, y cuece 10 minutos.$r$,$r$Tritura muy fino y ajusta la textura con caldo o leche. Nuez moscada o jengibre.$r$,$r$Sirve con picatostes dorados en sartén y un hilo de aceite.$r$]::text[],$r$Asar la calabaza antes en vez de hervirla concentra el dulzor: cambia la crema por completo.$r$,$r$4 días en nevera; se congela.$r$,true,true,$r$barato$r$,array[10,11,12,1,2,3]::smallint[]),
